// Timer: counts down for a fixed number of clock cycles, then goes high.
// One-shot terminal count: goes high for one clock cycle when the count
// reaches 0, then stays high until the count is reloaded.
module TopModule(input clk, input load, input [9:0] data, output reg tc);
  reg [9:0] count;
  always @(posedge clk) begin
    if (load) count <= data;
    else count <= count - 1'b1;
    tc <= (count == 10'd0);
  end
endmodule

